import type { Product, ProductVersion, TopicDocument } from "./contracts";
import { comparisonRequests } from "./comparison";

export interface KnowledgeCatalog {
  readonly schemaVersion: 1;
  readonly products: readonly Product[];
  readonly topics: readonly TopicDocument[];
}

export const MAX_CATALOG_BYTES = 2 * 1024 * 1024;
export const MAX_PRODUCTS = 16;
export const MAX_TOPICS = 256;
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/u;
const VERSION = /^(?:0|[1-9]\d{0,5})\.(?:0|[1-9]\d{0,5})$/u;
const LIFECYCLES = ["current", "maintained", "retired"] as const;

/** Parse actual JSON while refusing duplicate, escaped-equivalent object keys and excessive input. */
export function parseCatalogJson(text: string): unknown {
  if (typeof text !== "string" || new TextEncoder().encode(text).byteLength > MAX_CATALOG_BYTES) {
    throw new Error("JSON exceeds the two MiB input budget");
  }
  const parsed: unknown = JSON.parse(text);
  const stack: ({ keys: Set<string>; expectingKey: boolean } | null)[] = [];
  const tokens = text.matchAll(/"(?:\\.|[^"\\])*"|[{}[\],:]/gu);
  for (const [token] of tokens) {
    if (token === "{") {
      stack.push({ keys: new Set(), expectingKey: true });
      if (stack.length > 16) throw new Error("JSON nesting exceeds sixteen levels");
    } else if (token === "[") {
      stack.push(null);
      if (stack.length > 16) throw new Error("JSON nesting exceeds sixteen levels");
    } else if (token === "}" || token === "]") {
      stack.pop();
    } else if (token === ",") {
      const context = stack.at(-1);
      if (context) context.expectingKey = true;
    } else if (token.startsWith('"')) {
      const context = stack.at(-1);
      if (context?.expectingKey) {
        const key = JSON.parse(token) as string;
        if (context.keys.has(key)) throw new Error("Duplicate JSON object key");
        context.keys.add(key);
        context.expectingKey = false;
      }
    }
  }
  return parsed;
}

/** Require plain data records and a closed, explicitly named set of members. */
function object<const R extends readonly string[], const O extends readonly string[] = []>(
  value: unknown,
  required: R,
  optional: O = [] as unknown as O,
): Record<R[number] | O[number], unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Expected a plain data object");
  }
  const record = value as Record<string, unknown>;
  const prototype: unknown = Object.getPrototypeOf(value);
  if (
    (prototype !== Object.prototype && prototype !== null) ||
    Reflect.ownKeys(record).length !== Object.keys(record).length ||
    required.some((key) => !Object.hasOwn(record, key)) ||
    Object.keys(record).some((key) => !required.includes(key) && !optional.includes(key))
  ) {
    throw new Error("Missing or unknown object fields");
  }
  return record;
}

/** Keep original text rather than normalizing meaningful code, but refuse invalid or excessive strings. */
function string(value: unknown, minimum: number, maximum: number): string {
  if (
    typeof value !== "string" ||
    value.trim().length < minimum ||
    value.length > maximum ||
    !value.isWellFormed() ||
    /\p{Cc}/u.test(value.replaceAll("\t", "").replaceAll("\n", "").replaceAll("\r", ""))
  ) {
    throw new Error("Text is missing, malformed or outside its field budget");
  }
  return value;
}

/** Reject arrays beyond their per-field bounds before any domain transformation. */
function list(value: unknown, minimum: number, maximum: number): readonly unknown[] {
  if (
    !Array.isArray(value) ||
    Object.getPrototypeOf(value) !== Array.prototype ||
    value.length < minimum ||
    value.length > maximum ||
    Reflect.ownKeys(value).length !== value.length + 1 ||
    Object.keys(value).length !== value.length ||
    !Array.from({ length: value.length }, (_, index) => Object.hasOwn(value, index)).every(Boolean)
  ) {
    throw new Error("Array is outside its item budget");
  }
  return value;
}

/** Require one canonical non-path identity or one unambiguous major/minor version. */
function identity(value: unknown, version = false): string {
  const text = string(value, 1, version ? 13 : 128);
  if (!(version ? VERSION : SLUG).test(text)) throw new Error("Invalid catalog identity");
  return text;
}

/** Validate actual calendar dates, not normalized February 30 or locale-dependent dates. */
function date(value: unknown): string {
  const text = string(value, 10, 10);
  const parsed = new Date(text + "T00:00:00.000Z");
  if (
    !/^\d{4}-\d{2}-\d{2}$/u.test(text) ||
    !Number.isFinite(parsed.getTime()) ||
    parsed.toISOString().slice(0, 10) !== text
  ) {
    throw new Error("A canonical real calendar date is required");
  }
  return text;
}

/** Validate one catalog edition and its explicit lifecycle dates. */
function validateVersion(value: unknown): ProductVersion {
  const row = object(value, ["version", "lifecycle", "released"], ["endOfSupport"]);
  identity(row.version, true);
  if (!LIFECYCLES.includes(row.lifecycle as ProductVersion["lifecycle"]))
    throw new Error("Unknown lifecycle");
  const released = date(row.released);
  if (row.endOfSupport !== undefined && date(row.endOfSupport) < released)
    throw new Error("Support cannot end before release");
  if (row.lifecycle === "retired" && row.endOfSupport === undefined)
    throw new Error("Retired editions require an end of support date");
  return structuredClone(value) as ProductVersion;
}

/** Validate a complete product catalog row, preserving the authored edition order. */
function validateProduct(value: unknown): Product {
  const row = object(value, ["id", "name", "description", "versions"]);
  identity(row.id);
  string(row.name, 3, 90);
  string(row.description, 3, 400);
  const versions = list(row.versions, 0, 12).map(validateVersion);
  if (new Set(versions.map((item) => item.version)).size !== versions.length)
    throw new Error("Duplicate product edition");
  if (versions.filter((item) => item.lifecycle === "current").length > 1)
    throw new Error("Only one edition may be current");
  return structuredClone(value) as Product;
}

/** Validate every original topic field and complete warning against the selected catalog edition. */
function validateTopic(value: unknown, products: readonly Product[]): TopicDocument {
  const row = object(value, [
    "id",
    "topicSlug",
    "title",
    "summary",
    "productId",
    "productName",
    "version",
    "lifecycle",
    "contentType",
    "identifiers",
    "synonyms",
    "updated",
    "visibility",
    "provenance",
    "sections",
  ]);
  identity(row.id);
  identity(row.topicSlug);
  identity(row.productId);
  identity(row.version, true);
  string(row.title, 3, 90);
  string(row.summary, 20, 240);
  string(row.productName, 3, 90);
  date(row.updated);
  if (
    row.visibility !== "public" ||
    !["concept", "task", "reference", "troubleshooting"].includes(row.contentType as string)
  )
    throw new Error("Unsupported topic type or visibility metadata");
  const product = products.find((item) => item.id === row.productId);
  const version = product?.versions.find((item) => item.version === row.version);
  if (
    product?.name !== row.productName ||
    version === undefined ||
    version.lifecycle !== row.lifecycle
  )
    throw new Error("Topic applicability differs from its catalog");
  for (const entry of list(row.identifiers, 0, 12)) {
    if (!/^[A-Z0-9][A-Z0-9._-]{1,31}$/u.test(string(entry, 2, 32)))
      throw new Error("Invalid diagnostic identifier");
  }
  for (const entry of list(row.synonyms, 0, 12)) string(entry, 2, 128);
  const provenance = object(row.provenance, ["sourceId", "pages", "checksum"]);
  string(provenance.sourceId, 3, 128);
  if (!/^[a-f0-9]{64}$/u.test(string(provenance.checksum, 64, 64)))
    throw new Error("Invalid supplied source checksum");
  const pages = list(provenance.pages, 1, 256);
  if (
    pages.some(
      (page) => !Number.isSafeInteger(page) || (page as number) < 1 || (page as number) > 1_000_000,
    ) ||
    new Set(pages).size !== pages.length
  )
    throw new Error("Invalid or duplicate source pages");
  const sections = list(row.sections, 1, 64);
  const sectionIds = new Set();
  for (const value of sections) {
    const section = object(value, ["id", "title", "paragraphs"], ["steps", "code", "warning"]);
    const id = identity(section.id);
    if (sectionIds.has(id)) throw new Error("Duplicate stable section identity");
    sectionIds.add(id);
    string(section.title, 1, 160);
    for (const paragraph of list(section.paragraphs, 1, 64)) string(paragraph, 1, 8000);
    if (section.steps !== undefined)
      for (const step of list(section.steps, 1, 64)) string(step, 1, 8000);
    if (section.code !== undefined) string(section.code, 1, 32_768);
    if (section.warning !== undefined) {
      const warning = object(section.warning, ["level", "condition", "consequence", "avoidance"]);
      if (!["notice", "caution", "warning", "danger"].includes(warning.level as string))
        throw new Error("Unknown warning severity");
      for (const field of ["condition", "consequence", "avoidance"] as const)
        string(warning[field], 1, 4000);
    }
  }
  return structuredClone(value) as TopicDocument;
}

/** Admit one closed catalog with unambiguous product, edition, topic and canonical route identities. */
export function validateCatalog(value: unknown): KnowledgeCatalog {
  const row = object(value, ["schemaVersion", "products", "topics"]);
  if (row.schemaVersion !== 1) throw new Error("Unsupported knowledge catalog schema");
  const products = list(row.products, 0, MAX_PRODUCTS).map(validateProduct);
  if (new Set(products.map((item) => item.id)).size !== products.length)
    throw new Error("Duplicate product identity");
  const topics = list(row.topics, 0, MAX_TOPICS).map((item) => validateTopic(item, products));
  if (new Set(topics.map((item) => item.id)).size !== topics.length)
    throw new Error("Duplicate topic identity");
  if (
    new Set(topics.map((item) => `${item.productId}/${item.version}/${item.topicSlug}`)).size !==
    topics.length
  )
    throw new Error("Duplicate canonical topic edition");
  const catalog: KnowledgeCatalog = { schemaVersion: 1, products, topics };
  // A catalog must remain usable by the original complete comparison chooser, not fail after import/save.
  comparisonRequests(topics, products);
  if (new TextEncoder().encode(JSON.stringify(catalog)).byteLength > MAX_CATALOG_BYTES)
    throw new Error("Catalog exceeds its two MiB budget");
  return catalog;
}

/** Apply a complete explicit topic edit; renaming an existing stable ID is not an implicit second topic. */
export function applyTopic(
  catalog: KnowledgeCatalog,
  text: string,
  originalId?: string,
): KnowledgeCatalog {
  const topic = validateTopic(parseCatalogJson(text), catalog.products);
  if (
    originalId !== undefined &&
    (!catalog.topics.some((item) => item.id === originalId) || topic.id !== originalId)
  )
    throw new Error("Choose Add for a new topic identity");
  if (originalId === undefined && catalog.topics.some((item) => item.id === topic.id))
    throw new Error("Choose Edit for an existing topic identity");
  return validateCatalog({
    ...catalog,
    topics:
      originalId === undefined
        ? [...catalog.topics, topic]
        : catalog.topics.map((item) => (item.id === originalId ? topic : item)),
  });
}

/** Apply a product definition and keep its name explicit and consistent in all related topic records. */
export function applyProduct(
  catalog: KnowledgeCatalog,
  text: string,
  originalId?: string,
): KnowledgeCatalog {
  const product = validateProduct(parseCatalogJson(text));
  if (
    originalId !== undefined &&
    (!catalog.products.some((item) => item.id === originalId) || product.id !== originalId)
  )
    throw new Error("Choose Add for a new product identity");
  if (originalId === undefined && catalog.products.some((item) => item.id === product.id))
    throw new Error("Choose Edit for an existing product identity");
  return validateCatalog({
    ...catalog,
    products:
      originalId === undefined
        ? [...catalog.products, product]
        : catalog.products.map((item) => (item.id === originalId ? product : item)),
    topics: catalog.topics.map((topic) =>
      topic.productId === product.id ? { ...topic, productName: product.name } : topic,
    ),
  });
}

/** Retain older content while creating or updating an edition and synchronizing explicit lifecycle metadata. */
export function applyVersion(
  catalog: KnowledgeCatalog,
  productId: string,
  value: unknown,
  cloneFrom?: string,
): KnowledgeCatalog {
  const edition = validateVersion(value);
  const product = catalog.products.find((item) => item.id === productId);
  if (product === undefined) throw new Error("Select a known product");
  if (
    cloneFrom !== undefined &&
    (product.versions.some((item) => item.version === edition.version) ||
      !product.versions.some((item) => item.version === cloneFrom))
  )
    throw new Error("Clone requires a new edition and a known source edition");
  const versions = [
    ...product.versions
      .filter((item) => item.version !== edition.version)
      .map((item) =>
        edition.lifecycle === "current" && item.lifecycle === "current"
          ? { ...item, lifecycle: "maintained" as const }
          : item,
      ),
    edition,
  ];
  const topics = catalog.topics.map((topic) =>
    topic.productId === productId
      ? {
          ...topic,
          lifecycle:
            versions.find((item) => item.version === topic.version)?.lifecycle ?? topic.lifecycle,
        }
      : topic,
  );
  if (cloneFrom !== undefined)
    for (const topic of catalog.topics.filter(
      (item) => item.productId === productId && item.version === cloneFrom,
    ))
      topics.push({
        ...topic,
        id: `${topic.id}-${edition.version.replace(".", "-")}`,
        version: edition.version,
        lifecycle: edition.lifecycle,
      });
  return validateCatalog({
    ...catalog,
    products: catalog.products.map((item) =>
      item.id === productId ? { ...item, versions } : item,
    ),
    topics,
  });
}

/** Delete only an explicitly selected topic from a draft; earlier committed revisions are retained separately. */
export function removeTopic(catalog: KnowledgeCatalog, id: string): KnowledgeCatalog {
  if (!catalog.topics.some((item) => item.id === id)) throw new Error("Select a known topic");
  return validateCatalog({ ...catalog, topics: catalog.topics.filter((item) => item.id !== id) });
}

/** Serialize one validated catalog with deterministic object keys while preserving meaningful array order. */
export function canonicalCatalog(catalog: KnowledgeCatalog): string {
  const validated = validateCatalog(catalog);
  const order = (value: unknown): unknown =>
    Array.isArray(value)
      ? value.map(order)
      : value !== null && typeof value === "object"
        ? Object.fromEntries(
            Object.entries(value)
              .sort(([a], [b]) => a.localeCompare(b, "en-US"))
              .map(([key, item]) => [key, order(item)]),
          )
        : value;
  return JSON.stringify(order(validated));
}
